-- 4. Travel Tips
INSERT OR IGNORE INTO travel_tips (id, city_id, title, tip, category) VALUES (1, 1, 'Start forts early', 'Amber Fort gets crowded by late morning, especially in winter.', 'timing');
INSERT OR IGNORE INTO travel_tips (id, city_id, title, tip, category) VALUES (2, 2, 'Book Taj tickets ahead', 'Morning slots are best for photos and cooler weather.', 'booking');
INSERT OR IGNORE INTO travel_tips (id, city_id, title, tip, category) VALUES (3, 3, 'Use the metro', 'Delhi Metro is usually faster than road travel during peak hours.', 'transport');
INSERT OR IGNORE INTO travel_tips (id, city_id, title, tip, category) VALUES (4, 4, 'Plan around traffic', 'Keep buffer time between South Mumbai and suburbs.', 'transport');
INSERT OR IGNORE INTO travel_tips (id, city_id, title, tip, category) VALUES (5, 5, 'Reserve lake-view dinners', 'Sunset tables near Lake Pichola fill quickly in season.', 'booking');
INSERT OR IGNORE INTO travel_tips (id, city_id, title, tip, category) VALUES (6, 6, 'Respect ghat etiquette', 'Ask before photographing people during rituals.', 'culture');
INSERT OR IGNORE INTO travel_tips (id, city_id, title, tip, category) VALUES (7, 7, 'Check beach flags', 'Follow lifeguard warnings during monsoon and rough-sea days.', 'safety');
INSERT OR IGNORE INTO travel_tips (id, city_id, title, tip, category) VALUES (8, 8, 'Walk Fort Kochi', 'Many heritage streets, cafes, and galleries are best explored on foot.', 'transport');
INSERT OR IGNORE INTO travel_tips (id, city_id, title, tip, category) VALUES (9, 9, 'Temple head covering', 'Both men and women must cover their heads and remove shoes inside the Golden Temple.', 'culture');
INSERT OR IGNORE INTO travel_tips (id, city_id, title, tip, category) VALUES (10, 10, 'Rohtang Pass permits', 'Online permits are mandatory for vehicles visiting Rohtang Pass.', 'booking');
INSERT OR IGNORE INTO travel_tips (id, city_id, title, tip, category) VALUES (11, 11, 'Rafting seasons', 'River rafting is optimal from October to May; avoid monsoons.', 'adventure');
INSERT OR IGNORE INTO travel_tips (id, city_id, title, tip, category) VALUES (12, 12, 'Peak traffic buffer', 'Allow ample commute time between electronic city and central areas.', 'transport');
INSERT OR IGNORE INTO travel_tips (id, city_id, title, tip, category) VALUES (13, 13, 'Rent a bicycle or moped', 'Hampi''s ruins span 40+ sq km; cycling across boulder routes is magical.', 'transport');
INSERT OR IGNORE INTO travel_tips (id, city_id, title, tip, category) VALUES (14, 14, 'Pre-book Toy Train', 'Darjeeling Himalayan Railway joyrides sell out weeks ahead in peak holiday season.', 'booking');
INSERT OR IGNORE INTO travel_tips (id, city_id, title, tip, category) VALUES (15, 15, 'Shimla Walking Mall', 'Mall road is strictly vehicle-free; enjoy relaxed colonial heritage walks.', 'transport');
INSERT OR IGNORE INTO travel_tips (id, city_id, title, tip, category) VALUES (16, 16, 'Acclimatize in Leh', 'Rest completely for the first 24-48 hours in Leh to prevent altitude sickness (AMS).', 'health');
INSERT OR IGNORE INTO travel_tips (id, city_id, title, tip, category) VALUES (17, 17, 'Sunday Palace Illumination', 'Mysore Palace is illuminated by 100,000 bulbs every Sunday and holiday evening.', 'timing');
INSERT OR IGNORE INTO travel_tips (id, city_id, title, tip, category) VALUES (18, 18, 'Bargain for Shikara', 'Negotiate Shikara ride rates before embarking at Dal Lake ghats.', 'transport');
INSERT OR IGNORE INTO travel_tips (id, city_id, title, tip, category) VALUES (19, 19, 'Rent a Vintage Scooter', 'Exploring the French Quarter and coastal roads by scooter or cycle is ideal.', 'transport');
INSERT OR IGNORE INTO travel_tips (id, city_id, title, tip, category) VALUES (20, 20, 'Historic Biryani Trail', 'Try authentic mutton dum biryani around Charminar and Banjara Hills.', 'food');
INSERT OR IGNORE INTO travel_tips (id, city_id, title, tip, category) VALUES (21, 21, 'Ride the Historic Tram', 'Experience Asia''s oldest electric tramway connecting North and Central Kolkata.', 'transport');
INSERT OR IGNORE INTO travel_tips (id, city_id, title, tip, category) VALUES (22, 22, 'Flying Fox Zipline', 'Mehrangarh Fort features world-class aerial ziplining over desert battlements.', 'adventure');
INSERT OR IGNORE INTO travel_tips (id, city_id, title, tip, category) VALUES (23, 23, 'Carry Light Warmwear', 'Evenings in Nilgiris get crisp year-round; carry a light jacket or fleece.', 'comfort');
INSERT OR IGNORE INTO travel_tips (id, city_id, title, tip, category) VALUES (24, 24, 'Living Root Bridges Trip', 'Wear waterproof hiking shoes when descending to Cherrapunji and Mawlynnong root bridges.', 'adventure');

