INSERT OR IGNORE INTO reviews (id, city_id, traveler_name, rating, comment, travel_month) VALUES (101, 1, 'Neha Sen', 5, 'Jaipur was breathtaking. The sunset view from Nahargarh Fort over the Pink City is unforgettable.', 'November');
INSERT OR IGNORE INTO reviews (id, city_id, traveler_name, rating, comment, travel_month) VALUES (102, 1, 'Rohan Deshmukh', 4, 'Bazaars in the old city are vibrant with handcrafted jewelry and textiles. Delicious Dal Baati Churma.', 'January');
INSERT OR IGNORE INTO reviews (id, city_id, traveler_name, rating, comment, travel_month) VALUES (103, 2, 'Vikram Mehta', 5, 'Taj Mahal at sunrise is magical beyond words. Pre-booking skip-the-line tickets saved immense time.', 'December');
INSERT OR IGNORE INTO reviews (id, city_id, traveler_name, rating, comment, travel_month) VALUES (104, 3, 'Elena Rostova', 5, 'The contrasts between Old Delhi street food and New Delhi monuments are astonishing.', 'February');
INSERT OR IGNORE INTO reviews (id, city_id, traveler_name, rating, comment, travel_month) VALUES (105, 6, 'Swami Nityanand', 5, 'Ganga Aarti at Dashashwamedh Ghat moved my soul. Truly the spiritual heart of India.', 'October');
INSERT OR IGNORE INTO reviews (id, city_id, traveler_name, rating, comment, travel_month) VALUES (106, 7, 'Arjun Nair', 5, 'South Goa beaches are so peaceful and pristine. Scooter ride along coastal coconut groves was pure joy.', 'December');
INSERT OR IGNORE INTO reviews (id, city_id, traveler_name, rating, comment, travel_month) VALUES (107, 8, 'Claire Dupont', 5, 'Fort Kochi colonial cafes and Kathakali cultural dances made our holiday extraordinary.', 'January');
INSERT OR IGNORE INTO reviews (id, city_id, traveler_name, rating, comment, travel_month) VALUES (108, 16, 'Tenzin Gyatso', 5, 'Pangong Tso azure waters nestled between high Himalayas felt like another planet.', 'July');
INSERT OR IGNORE INTO reviews (id, city_id, traveler_name, rating, comment, travel_month) VALUES (109, 21, 'Debabrata Das', 5, 'Victoria Memorial gardens, colonial tramways, and authentic sandesh sweets on Park Street.', 'November');
